// Launch math: generated by OpenRouter (nvidia/nemotron-3-ultra-550b-a55b:free) and reviewed/kept.
// Pure functions, no engine dependency, so the same file ports to Luau math 1:1.

export function computeRange({ gunpowder = 0, powerMult = 1, firepowerBonus = 0 }) {
  const base = 30 + 3.2 * Math.max(0, gunpowder);
  const mult = Math.max(0.55, Math.min(1.15, powerMult)) * (1 + Math.max(0, firepowerBonus));
  const range = base * mult;
  return Math.max(8, Math.min(300, range));
}

export function gaugeSpeedFor(gunpowder) {
  return Math.min(1.4, 0.55 + Math.max(0, gunpowder) * 0.02);
}

export function createGauge({ speed = 1, zoneStart = 0.4, zoneEnd = 0.6 }) {
  let value = 0;
  let dir = 1;
  return {
    get value() { return value; },
    get dir() { return dir; },
    update(dt) {
      value += dir * speed * dt;
      if (value >= 1) { value = 1; dir = -1; }
      else if (value <= 0) { value = 0; dir = 1; }
    },
    getZone() { return { start: zoneStart, end: zoneEnd }; }
  };
}

export function judgeAccuracy(value, zoneStart, zoneEnd) {
  const inZone = value >= zoneStart && value <= zoneEnd;
  const nearZone = value >= zoneStart - 0.08 && value <= zoneEnd + 0.08;
  if (inZone) return { tier: "perfect", mult: 1.0, label: "PERFECT" };
  if (nearZone) return { tier: "good", mult: 0.8, label: "GOOD" };
  return { tier: "miss", mult: 0.55, label: "MISS" };
}

export function flightDuration(range) {
  const raw = 0.55 + Math.sqrt(Math.max(0, range)) * 0.11;
  return Math.max(0.6, Math.min(3.2, raw));
}

export function flightPosition({ from, to, t, height }) {
  const clampedT = Math.max(0, Math.min(1, t));
  const x = from.x + (to.x - from.x) * clampedT;
  const z = from.z + (to.z - from.z) * clampedT;
  const y = 4 * height * clampedT * (1 - clampedT);
  return { x, y, z };
}

export function returnCost(distance) {
  return Math.max(5, Math.ceil(Math.max(0, distance) / 12));
}

export default {
  computeRange,
  gaugeSpeedFor,
  createGauge,
  judgeAccuracy,
  flightDuration,
  flightPosition,
  returnCost
};